function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('저장 공간이 부족합니다. 학습 기록을 백업해 주세요.')}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastHandle);toastHandle=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function catName(c){return {law:'전파법규',english:'항공영어',practical:'실기'}[c]||c}
function chip(c){return `<span class="pill ${c==='english'?'purple':c==='practical'?'warm':''}">${catName(c)}</span>`}
function progress(c){const all=DB.chapters.filter(x=>!c||x.category===c);const n=all.filter(x=>state.completed.includes(x.id)).length;return {n,total:all.length,pct:all.length?Math.round(n/all.length*100):0}}
function sourceLink(id){const s=DB.sources.find(x=>x.id===id);return s?`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ${icon('external',11)}</a>`:''}
function button(label,act,cls='secondary',attrs=''){return `<button class="btn ${cls}" data-action="${act}" ${attrs}>${label}</button>`}
function pageHead(eyebrow,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`}
function notice(s,warn=false){return `<div class="notice ${warn?'warn':''}">${icon('info',17)}<div>${s}</div></div>`}
function nav(){const r=route.split('/')[0];const chapter=DB.chapters.find(c=>route===`chapter/${c.id}`);let active=chapter?.category||(r==='legal'?'law':r);const navs=[['home','home','학습 대시보드'],['law','law','전파법규'],['english','english','항공영어'],['quiz','quiz','CBT 연습'],['practical','headphones','실기 연습실'],['review','bookmark','오답 · 북마크'],['sources','folder','자료 · 개정 확인']];$('#sidebar').innerHTML=`<a href="#home" class="brand"><span class="brand-mark">${icon('plane',24)}</span><div>AERO NOTE<small>항공무선통신사 학습실</small></div></a><button class="search-btn" data-action="search"><span>${icon('search',15)} &nbsp; 개념 · 용어 검색</span><span class="key">⌘ K</span></button><div class="nav-label">MY STUDY SPACE</div>${navs.map(([id,ic,t],i)=>`${i===3?'<div class="nav-label">PRACTICE & REVIEW</div>':''}<a class="nav-item ${active===id?'active':''}" href="#${id}" ${active===id?'aria-current="page"':''}>${icon(ic)}<span>${t}</span>${id==='review'&&state.wrong.length?`<span class="count">${state.wrong.length}</span>`:''}</a>`).join('')}<div class="sidebar-foot"><div class="tiny muted">나의 개념 학습</div><div class="progress"><i style="width:${progress().pct}%"></i></div><div class="tiny"><strong>${progress().pct}%</strong><span class="muted"> &nbsp; ${progress().n} / ${progress().total}개 단원</span></div><div class="spacer"></div><div class="small-note muted">기준일 2026.10.25<br>법령 출처와 시행일을 함께 확인하세요.</div></div>`;$('#topbar').innerHTML=`<button class="menu-toggle" data-action="menu" aria-label="메뉴 열기">${icon('menu')}</button><div class="breadcrumb"><a href="#home">학습실</a>${icon('chevron',12)}<span>${chapter?esc(chapter.title):({home:'나의 학습 현황',law:'전파법규',english:'항공영어',quiz:'CBT 연습',practical:'실기 연습실',review:'복습 노트',sources:'자료 · 개정 확인',legal:'현행 조문 읽기',vocabulary:'항공영어 단어장'}[r]||'학습실')}</span></div><div class="topbar-right"><span class="verify-text"><i class="live-dot"></i>2026.10.25 기준 자료</span><button data-action="search" aria-label="검색">${icon('search',17)}</button><span class="avatar">A</span></div>`}
function navigate(){if(recording&&recording.state==='recording')recording.stop();recordStream?.getTracks().forEach(t=>t.stop());clearInterval(timerHandle);clearInterval(practiceTimer);if('speechSynthesis'in window)speechSynthesis.cancel();route=decodeURIComponent(location.hash.slice(1)||'home');document.body.classList.toggle('exam-mode',route==='quiz'&&!!state.quiz&&!state.quiz.finished);nav();const main=$('#main');main.innerHTML='';const [r,id]=route.split('/');if(r==='chapter')main.innerHTML=lessonPage(id);else if(r==='law'||r==='english')main.innerHTML=categoryPage(r);else if(r==='quiz')main.innerHTML=quizPage();else if(r==='practical')main.innerHTML=practicalPage();else if(r==='review')main.innerHTML=reviewPage();else if(r==='sources')main.innerHTML=sourcesPage();else if(r==='legal')main.innerHTML=legalPage();else if(r==='vocabulary')main.innerHTML=vocabularyPage();else main.innerHTML=homePage();if(r==='quiz'&&state.quiz&&!state.quiz.finished)startQuizTimer();if(r==='practical')wireAudio();window.scrollTo(0,0);closeModal();}
function homePage(){const p=progress();const last=DB.chapters.find(x=>x.id===state.lastChapter)||DB.chapters[0];const totalQ=state.history.reduce((s,h)=>s+h.total,0),correct=state.history.reduce((s,h)=>s+h.correct,0);return `${pageHead('STUDY DASHBOARD','항공무선통신사 학습실','전파법규 · 항공영어 · 실기. 개념을 읽고, 문제로 확인하고, 반복해서 익히세요.')}<section class="hero"><div class="hero-text"><div class="eyebrow">개념 학습 → CBT 연습 → 오답 복습</div><h2 class="hero-title">오늘의 학습을 시작하세요.</h2><p>현행 법령을 근거로 정리한 개념 노트와 항공영어,<br>수신·송신 연습을 한곳에서 확인할 수 있습니다.</p><div class="actions"><a class="btn" href="#chapter/${last?.id||''}">${state.lastChapter?'이어서 학습하기':'첫 개념 시작하기'} ${icon('arrow',15)}</a><a class="btn ghost" href="#quiz">CBT 연습 ${icon('chevron',14)}</a></div></div><div class="hero-art" aria-hidden="true"><div class="radar"><div class="cross"></div><div class="cross"></div></div><div class="hero-plane">${icon('plane',67)}</div><i class="art-dot"></i><span class="radar-label">37° N &nbsp; 127° E &nbsp; / &nbsp; LEARNING IN PROGRESS</span></div></section><div class="stats"><div class="stat"><div class="stat-label">${icon('book',14)} 개념 학습</div><div class="stat-value">${p.n}<small>/ ${p.total} 단원</small></div></div><div class="stat"><div class="stat-label">${icon('quiz',14)} 풀어본 문제</div><div class="stat-value">${totalQ}<small>문항</small></div></div><div class="stat"><div class="stat-label">${icon('check',14)} 누적 정답률</div><div class="stat-value">${totalQ?Math.round(correct/totalQ*100):'–'}<small>%</small></div></div><div class="stat"><div class="stat-label">${icon('bookmark',14)} 다시 볼 문제</div><div class="stat-value">${state.wrong.length}<small>문항</small></div></div></div><div class="section-head"><h2>무엇을 공부할까요?</h2><a href="#sources">학습 범위 확인 ${icon('arrow',13)}</a></div><div class="grid-3">${[['law','law','규정의 구조부터, 정확하게','전파법·시행령, 무선국 운용 규정, 항공업무 기술기준을 연결해 학습합니다.',''],['english','english','익숙한 표현이, 정확한 응답으로','통신용어와 전문, 기상·비행 영어를 예문과 함께 익힙니다.','purple'],['practical','headphones','듣고, 쓰고, 말하는 연습','A–D 수신 음원과 받아쓰기, 송신 타이머로 실기 감각을 기릅니다.','warm']].map(([c,ic,t,d,cl])=>{const p=progress(c);return `<a class="subject-card" href="#${c}"><div class="subject-top"><div class="icon-box ${cl}">${icon(ic,23)}</div><span class="pill ${cl}">${c==='practical'?'PRACTICE':c==='law'?'SUBJECT 01':'SUBJECT 02'}</span></div><h3>${catName(c)}${c==='practical'?' 연습실':''}</h3><p>${d}</p><div class="card-bottom"><span>${c==='practical'?'수신 · 송신 · 통화표':`${p.total}개 단원 · ${p.pct}% 학습`}</span>${icon('arrow',17)}</div></a>`}).join('')}</div><div class="dashboard-lower"><section class="panel"><div class="section-head"><h2>법령 확인 노트</h2><a href="#sources">출처 보기 ${icon('external',12)}</a></div><div class="update-row"><span class="date">2026.10.22</span><div><strong>전파법 · 시행령 현행본 확인</strong><p>운용 규정 2026.10.16, 항공업무 기술기준 2025.12.22 시행본을 함께 반영합니다.</p></div></div><div class="update-row"><span class="date">법령 체계</span><div><strong>전파법과 전파법 시행령 구분</strong><p>전파법은 법률, 전파법 시행령은 대통령령입니다. 고시의 세부 기준까지 연결해 읽습니다.</p></div></div><div class="update-row"><span class="date">학습 자료</span><div><strong>과거 기출은 출제 개념 확인용</strong><p>2007–2016년 자료의 법령 정답을 현재 정답으로 간주하지 않습니다.</p></div></div></section><section class="panel"><h2>권장 학습 순서</h2>${[['개념 노트 읽기','법령 구조와 영어 표현의 쓰임부터 이해하세요.'],['CBT로 확인하기','선택 과목 문제를 풀고 해설의 근거를 확인하세요.'],['오답과 실기 반복하기','틀린 개념을 다시 읽고 수신·송신을 연습하세요.']].map(([a,b],i)=>`<div class="study-step"><span class="step-num">${i+1}</span><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</section></div>${notice('이 학습실은 요청하신 <b>전파법규·영어와 실기</b>에 집중합니다. 무선설비취급방법·통신보안의 과목면제 여부는 본인의 접수 내역에서 확인하세요. 전체 필기시험을 대체하는 과정은 아닙니다.')}`}
function categoryPage(cat){const chapters=DB.chapters.filter(c=>c.category===cat);const groups=[...new Set(chapters.map(c=>c.section))];const p=progress(cat);return `${pageHead(cat==='law'?'RADIO REGULATIONS':'AVIATION ENGLISH',catName(cat),cat==='law'?'법률의 큰 틀에서 실제 통신 절차까지, 근거를 따라 이해합니다.':'단어의 뜻에서 전문 해석까지, 맥락 속에서 항공영어를 익힙니다.',cat==='english'?'<a href="#vocabulary" class="btn secondary">단어장 열기</a>':'<a href="#legal" class="btn secondary">현행 조문 읽기</a>')}<div class="panel" style="margin-bottom:24px"><div class="section-head"><span><strong>${p.n}</strong> / ${p.total}개 단원 완료</span><span class="pill">${p.pct}%</span></div><div class="progress"><i style="width:${p.pct}%"></i></div><div class="tiny muted">각 단원의 ‘학습 완료’를 누르면 진행률이 기록됩니다.</div></div><div id="curriculum-${cat}" class="subject-curriculum"><div class="section-head"><h2>전체 개념 목차</h2></div>${groups.map((g,i)=>`<section class="chapter-group"><h2><span class="badge-number">${String(i+1).padStart(2,'0')}</span> ${esc(g.replace(/^\d+\s*/, ''))}</h2><div class="chapter-list">${chapters.filter(c=>c.section===g).map(c=>`<a class="chapter-row" href="#chapter/${c.id}"><span class="chapter-index">${String(chapters.indexOf(c)+1).padStart(2,'0')}</span><div><h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p></div><span class="end">${state.bookmarks.includes(c.id)?icon('bookmark',14):''}${state.completed.includes(c.id)?'<span class="pill">학습 완료</span>':icon('chevron',16)}</span></a>`).join('')}</div></section>`).join('')}</div>${notice('문항은 개념 확인을 위해 새로 작성한 학습용 문제입니다. 실제 CBT 문제은행의 전체 문항 또는 공식 복원문제를 의미하지 않습니다.')}`}
function bodyText(text){return esc(text).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')}
function lessonPage(id){const c=DB.chapters.find(x=>x.id===id);if(!c)return '<div class="empty">해당 단원을 찾을 수 없습니다. <a href="#home">학습실로</a></div>';state.lastChapter=id;save();const siblings=DB.chapters.filter(x=>x.category===c.category),idx=siblings.indexOf(c);return `<div class="page-head"><a class="text-link" href="#${c.category}">← ${catName(c.category)} 목차</a><div class="actions">${button(`${icon('bookmark',15)} ${state.bookmarks.includes(id)?'북마크됨':'북마크'}`,'bookmark','secondary small',`data-id="${id}"`)}${button('인쇄','print','secondary small')}</div></div><div class="lesson-layout"><article class="lesson"><div class="lesson-meta">${chip(c.category)}<span class="pill outline">${esc(c.section)}</span></div><h1>${esc(c.title)}</h1><p class="lead">${esc(c.summary)}</p>${c.category==='law'?'<a class="text-link" href="#legal">현행 조문과 표 찾아보기 '+icon('external',12)+'</a>':''}${c.notice?notice(esc(c.notice),true):''}${c.topics.map((t,i)=>`<section id="topic-${i}" class="lesson-section"><h2>${esc(t.title)}</h2><p>${bodyText(t.body)}</p>${t.bullets?.length?`<ul>${t.bullets.map(b=>`<li>${bodyText(b)}</li>`).join('')}</ul>`:''}${t.table?`<div class="table-wrap"><table>${t.table.map((row,j)=>`<tr>${row.map(cell=>`<${j?'td':'th'}>${esc(cell)}</${j?'td':'th'}>`).join('')}</tr>`).join('')}</table></div>`:''}</section>`).join('')}${c.check?`<div class="lesson-check"><div class="eyebrow">QUICK CHECK</div><h3>${esc(c.check.question)}</h3><details><summary>정답과 설명 보기</summary><p><strong>${esc(c.check.answer)}</strong><br>${esc(c.check.explanation)}</p></details></div>`:''}${conceptPracticeSection(c.category,c.id)}<section class="lesson-section"><h2>나의 학습 메모</h2><textarea class="notes" id="lesson-note" data-chapter="${id}" placeholder="헷갈린 개념, 암기할 내용, 나만의 예시를 적어보세요." aria-label="학습 메모">${esc(state.notes[id]||'')}</textarea><div class="tiny muted" id="note-status">입력한 메모는 이 브라우저에 자동 저장됩니다.</div></section><div class="lesson-controls">${button(`${icon('check',16)} ${state.completed.includes(id)?'학습 완료됨':'학습 완료'}`,'complete',state.completed.includes(id)?'secondary':'',`data-id="${id}"`)}<div class="actions">${idx>0?`<a class="btn secondary small" href="#chapter/${siblings[idx-1].id}">이전</a>`:''}${idx<siblings.length-1?`<a class="btn small" href="#chapter/${siblings[idx+1].id}">다음 단원 ${icon('arrow',14)}</a>`:''}</div></div><div class="source-links" style="margin-top:28px"><div class="tiny muted">근거 자료 · 기준일 2026.10.25</div>${(c.sourceIds||[]).map(sourceLink).join('<br>')}</div></article><aside class="toc"><h3>이 단원에서 배울 내용</h3>${c.topics.map((t,i)=>`<a href="#topic-${i}" data-action="scroll-topic" data-topic="topic-${i}">${esc(t.title)}</a>`).join('')}<div class="source-links"><h3>원문과 함께 읽기</h3>${(c.sourceIds||[]).map(sourceLink).join('')}</div></aside></div>`}
function shuffle(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function quizPage(){if(state.quiz)return state.quiz.finished?quizResult():activeQuiz();const qn=DB.questions.length;return `${pageHead('CBT PRACTICE','개념을 실력으로 바꾸는 시간.','전파법규·항공영어를 골라, 배운 내용을 문제로 확인하세요.')}<div class="grid-2"><section class="panel"><h2>나의 연습 설정</h2><div class="quiz-settings"><div class="field"><label for="quiz-subject">연습 과목</label><select id="quiz-subject"><option value="all">전파법규 + 항공영어</option><option value="law">전파법규</option><option value="english">항공영어</option><option value="wrong">오답 다시 풀기 (${state.wrong.length}문항)</option></select></div><div class="field"><label for="quiz-count">문항 수</label><select id="quiz-count"><option value="10">10문항 · 가볍게 확인</option><option value="20">20문항 · 집중 연습</option><option value="40">40문항 · 두 과목 연습</option><option value="999">선택 과목 전체</option></select></div><div class="field"><label for="quiz-time">연습 시간</label><select id="quiz-time"><option value="0">시간 제한 없음</option><option value="10">10분</option><option value="20">20분</option><option value="40">40분</option></select></div><div class="field"><label for="quiz-mode">해설 확인</label><select id="quiz-mode"><option value="exam">제출 후 해설 보기</option><option value="learn">매 문항 정답 확인</option></select></div></div>${button(`연습 시작하기 ${icon('arrow',15)}`,'start-quiz','full')}<p class="field-hint" style="margin:14px 0 0">총 ${qn}개 창작 개념문항에서 무작위 출제합니다. 선택한 수보다 문제가 적으면 가능한 문항으로 구성합니다. 혼합 연습은 두 과목을 균등하게 배분합니다.</p></section><section class="panel"><div class="eyebrow">BEFORE YOU START</div><h2>답을 외우기보다,<br>근거를 이해하세요.</h2><div class="study-step"><span class="step-num">1</span><div><strong>모르는 문제는 표시</strong><p>다시 보기 표시를 남기고 다른 문제로 이동할 수 있습니다.</p></div></div><div class="study-step"><span class="step-num">2</span><div><strong>해설에서 개념으로</strong><p>채점 후 연결된 단원에서 관련 내용을 다시 읽어보세요.</p></div></div><div class="study-step"><span class="step-num">3</span><div><strong>오답은 자동으로 보관</strong><p>다시 풀어서 맞힌 문제는 오답 목록에서 해제됩니다.</p></div></div>${notice('설정 시간과 점수는 개인 연습용입니다. 이 화면은 요청한 두 과목을 대상으로 하며 실제 전체 시험의 합격 여부를 판정하지 않습니다.')}</section></div>${state.history.length?`<div class="spacer"></div><div class="section-head"><h2>최근 연습 기록</h2><a href="#review">복습 노트 ${icon('arrow',13)}</a></div><div class="panel">${state.history.slice(0,5).map(h=>`<div class="record-row"><div class="icon-box">${icon('quiz')}</div><div class="grow"><h3>${esc(h.label)}</h3><p>${new Date(h.date).toLocaleString('ko-KR')} · ${h.total}문항</p></div><strong>${Math.round(h.correct/h.total*100)}점</strong></div>`).join('')}</div>`:''}`}
function startQuiz(forced){const subject=forced?'wrong':$('#quiz-subject').value;let pool=DB.questions.filter(q=>subject==='all'||(subject==='wrong'?state.wrong.includes(q.id):q.category===subject));const count=forced?pool.length:Number($('#quiz-count').value),minutes=forced?0:Number($('#quiz-time').value),mode=forced?'learn':$('#quiz-mode').value;if(!pool.length){toast('선택한 범위에 문제가 없습니다.');return}let selected;if(subject==='all'){const a=shuffle(pool.filter(q=>q.category==='law')),b=shuffle(pool.filter(q=>q.category==='english'));selected=[];while(selected.length<Math.min(count,pool.length)){if(a.length)selected.push(a.pop());if(selected.length<Math.min(count,pool.length)&&b.length)selected.push(b.pop())}selected=shuffle(selected)}else selected=shuffle(pool).slice(0,count);state.quiz={ids:selected.map(q=>q.id),answers:{},flags:[],revealed:[],index:0,started:Date.now(),deadline:minutes?Date.now()+minutes*60000:0,mode,label:subject==='all'?'전파법규 + 항공영어':subject==='wrong'?'오답 복습':catName(subject),finished:false};save();if(route!=='quiz')location.hash='quiz';else navigate()}
function activeQuiz(){const s=state.quiz,q=DB.questions.find(x=>x.id===s.ids[s.index]);if(!q){state.quiz=null;save();return quizPage()}const shown=s.revealed.includes(q.id);return `${pageHead('CBT 연습',s.label,`${s.mode==='learn'?'매 문항 정답 확인':'제출 후 채점'} · ${s.ids.length}문항 · 답안 자동 저장`,'<a class="btn secondary" href="#home">학습실로 돌아가기</a>')}<div class="quiz-layout"><section class="panel"><div class="quiz-top"><span class="quiz-count">문제 <b>${s.index+1}</b> / ${s.ids.length} &nbsp; ${chip(q.category)}</span><div class="timer" id="quiz-timer">${s.deadline?'--:--':'시간 제한 없음'}</div></div><h2 class="quiz-prompt">${esc(q.prompt)}</h2>${q.options.map((o,i)=>`<button class="answer-option ${s.answers[q.id]===i?'selected':''} ${shown&&i===q.answer?'correct':''} ${shown&&s.answers[q.id]===i&&i!==q.answer?'incorrect':''}" data-action="answer" data-index="${i}" ${shown?'disabled':''} aria-pressed="${s.answers[q.id]===i}"><span class="option-no">${i+1}</span><span>${esc(o)}</span></button>`).join('')}${shown?`<div class="explanation"><strong>${s.answers[q.id]===q.answer?'정답입니다.':'정답은 '+(q.answer+1)+'번입니다.'}</strong><br>${esc(q.explanation)}<br><a class="text-link" href="#chapter/${q.chapterId}">관련 개념 읽기 ${icon('arrow',13)}</a></div>`:''}<div class="actions" style="margin-top:20px">${button(`${icon('flag',14)} ${s.flags.includes(q.id)?'다시 보기 표시됨':'다시 보기'}`,'flag','secondary small')}${s.mode==='learn'&&!shown?button('정답 확인','reveal','small'):''}</div><div class="lesson-controls">${button('이전 문제','prev-question','secondary',s.index===0?'disabled':'')}${button(s.index===s.ids.length-1?'답안 제출':'다음 문제 '+icon('arrow',14),s.index===s.ids.length-1?'submit-quiz':'next-question','')}</div></section><aside class="panel sticky-panel"><h3>답안 현황</h3><div class="tiny muted">${Object.keys(s.answers).length} / ${s.ids.length}문항 답변</div><div class="qgrid">${s.ids.map((id,i)=>`<button class="${s.answers[id]!==undefined?'done':''} ${i===s.index?'current':''} ${s.flags.includes(id)?'flag':''}" data-action="jump-question" data-index="${i}" aria-label="${i+1}번 문제${s.answers[id]!==undefined?', 답변 완료':''}">${i+1}</button>`).join('')}</div><p class="tiny muted">파랑: 답변 완료 · 작은 점: 다시 보기</p>${button('답안 제출하기','submit-quiz','full')}<div class="spacer"></div>${button('이번 연습 종료','cancel-quiz','ghost small full')}</aside></div>`}
function startQuizTimer(){function tick(){const q=state.quiz;if(!q||q.finished)return;const el=$('#quiz-timer');if(!q.deadline)return;if(Date.now()>=q.deadline){finishQuiz();toast('연습 시간이 끝나 자동 채점했습니다.');return}const sec=Math.ceil((q.deadline-Date.now())/1000);if(el)el.textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}tick();timerHandle=setInterval(tick,1000)}
function finishQuiz(){const s=state.quiz;if(!s||s.finished)return;s.finished=true;s.ended=Date.now();let correct=0;for(const id of s.ids){const q=DB.questions.find(x=>x.id===id);if(s.answers[id]===q.answer){correct++;state.wrong=state.wrong.filter(x=>x!==id)}else if(!state.wrong.includes(id))state.wrong.push(id)}state.history.unshift({date:Date.now(),label:s.label,total:s.ids.length,correct});state.history=state.history.slice(0,100);save();navigate()}
function quizResult(){const s=state.quiz,qs=s.ids.map(id=>DB.questions.find(q=>q.id===id)),correct=qs.filter(q=>s.answers[q.id]===q.answer).length;return `${pageHead('PRACTICE RESULT','확인한 만큼, 한 걸음 앞으로.','정답의 이유를 읽고 헷갈린 개념을 다시 정리해 보세요.',button('다른 문제 연습','new-quiz',''))}<div class="grid-2"><div class="panel"><div class="eyebrow">${esc(s.label)}</div><div class="score">${Math.round(correct/qs.length*100)}<small>점</small></div><p class="muted">${qs.length}문항 중 ${correct}문항 정답 · ${Math.round((s.ended-s.started)/60000)}분 학습</p><div class="tiny muted">개념 연습 점수이며 실제 시험 합격 판정이 아닙니다.</div></div><div class="panel"><h3>과목별 정답률</h3>${['law','english'].map(c=>{const a=qs.filter(q=>q.category===c),n=a.filter(q=>s.answers[q.id]===q.answer).length;return a.length?`<div class="section-head" style="margin-top:18px"><span>${catName(c)}</span><b>${n} / ${a.length}</b></div><div class="progress"><i style="width:${n/a.length*100}%"></i></div>`:''}).join('')}<a class="text-link" href="#review">오답 노트로 이동 ${icon('arrow',14)}</a></div></div><div class="spacer"></div><section class="panel"><h2>문항별 해설</h2>${qs.map((q,i)=>{const ok=s.answers[q.id]===q.answer;return `<details class="result-item" ${ok?'':'open'}><summary><span class="${ok?'correct-text':'wrong-text'}">${ok?'✓':'✕'} ${i+1}.</span> ${esc(q.prompt)}</summary><div class="explanation"><div>나의 답: ${s.answers[q.id]===undefined?'미응답':esc(q.options[s.answers[q.id]])}</div><strong>정답 ${q.answer+1}. ${esc(q.options[q.answer])}</strong><p>${esc(q.explanation)}</p><a class="text-link" href="#chapter/${q.chapterId}">관련 단원 학습 ${icon('arrow',13)}</a></div></details>`}).join('')}</section>`}
function reviewPage(){const wrong=state.wrong.map(id=>DB.questions.find(q=>q.id===id)).filter(Boolean),bookmarks=state.bookmarks.map(id=>DB.chapters.find(c=>c.id===id)).filter(Boolean),notes=DB.chapters.filter(c=>state.notes[c.id]?.trim());return `${pageHead('REVIEW NOTE','다시 볼수록, 더 선명하게.','오답과 북마크, 직접 적은 메모가 한곳에 모입니다.',button('학습 기록 백업','export-state','secondary'))}<div class="tabs"><button class="active" data-action="review-tab" data-tab="wrong">오답 ${wrong.length}</button><button data-action="review-tab" data-tab="bookmarks">북마크 ${bookmarks.length}</button><button data-action="review-tab" data-tab="notes">나의 메모 ${notes.length}</button><button data-action="review-tab" data-tab="records">학습 기록</button></div><div id="review-wrong" class="review-pane">${wrong.length?`<div class="section-head"><span class="tiny muted">다시 풀어 맞힌 문제는 목록에서 자동 해제됩니다.</span>${button('오답 다시 풀기','retry-wrong','small')}</div><section class="panel">${wrong.map((q,i)=>`<details class="result-item"><summary>${chip(q.category)} &nbsp; ${esc(q.prompt)}</summary><div class="explanation"><b>${q.answer+1}. ${esc(q.options[q.answer])}</b><p>${esc(q.explanation)}</p><a class="text-link" href="#chapter/${q.chapterId}">개념 다시 읽기 ${icon('arrow',13)}</a></div>${button('복습 완료 · 목록에서 해제','remove-wrong','secondary small',`data-id="${q.id}"`)}</details>`).join('')}</section>`:`<div class="empty">${icon('check',32)}<h3>아직 쌓인 오답이 없어요.</h3><p>CBT 연습 후 다시 볼 문제가 여기에 모입니다.</p><a class="btn" href="#quiz">CBT 연습하기</a></div>`}</div><div id="review-bookmarks" class="review-pane" hidden>${bookmarks.length?`<div class="chapter-list">${bookmarks.map(c=>`<a class="chapter-row" href="#chapter/${c.id}">${chip(c.category)}<div><h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p></div><span class="end">${icon('chevron',15)}</span></a>`).join('')}</div>`:'<div class="empty"><h3>기억해 둘 단원을 북마크해 보세요.</h3><p>단원 상단의 북마크 버튼으로 저장할 수 있습니다.</p></div>'}</div><div id="review-notes" class="review-pane" hidden>${notes.length?notes.map(c=>`<section class="panel" style="margin-bottom:15px"><a href="#chapter/${c.id}"><h3>${esc(c.title)} ${icon('external',13)}</h3></a><p style="white-space:pre-wrap;font-size:13px">${esc(state.notes[c.id])}</p></section>`).join(''):'<div class="empty"><h3>나의 말로 개념을 정리해 보세요.</h3><p>각 단원 아래에서 작성한 메모가 여기에 모입니다.</p></div>'}</div><div id="review-records" class="review-pane" hidden><div class="panel"><h3>학습 기록 관리</h3><p class="section-note">진행률, 북마크, 메모와 문제풀이 기록은 현재 브라우저에 저장됩니다. 다른 기기로 옮기려면 백업 파일을 내보낸 뒤 불러오세요.</p><div class="actions">${button('백업 파일 다운로드','export-state','secondary')}<label class="btn secondary" for="import-state">백업 불러오기</label><input id="import-state" type="file" accept="application/json,.json" hidden>${button('기록 초기화','reset-state','danger')}</div><div class="spacer"></div>${state.history.map(h=>`<div class="record-row"><div class="grow"><h3>${esc(h.label)}</h3><p>${new Date(h.date).toLocaleString('ko-KR')}</p></div><strong>${h.correct}/${h.total} 정답</strong></div>`).join('')||'<p class="muted tiny">아직 완료한 연습이 없습니다.</p>'}</div></div>`}
const alphabet=[['A','Alfa'],['B','Bravo'],['C','Charlie'],['D','Delta'],['E','Echo'],['F','Foxtrot'],['G','Golf'],['H','Hotel'],['I','India'],['J','Juliett'],['K','Kilo'],['L','Lima'],['M','Mike'],['N','November'],['O','Oscar'],['P','Papa'],['Q','Quebec'],['R','Romeo'],['S','Sierra'],['T','Tango'],['U','Uniform'],['V','Victor'],['W','Whiskey'],['X','X-ray'],['Y','Yankee'],['Z','Zulu']];
function practicalPage(){return `${pageHead('RADIO PRACTICE ROOM','실기 연습실','귀로 듣고, 손으로 쓰고, 정확하게 말하는 연습.')}<div class="tabs"><button class="${practiceTab==='receive'?'active':''}" data-action="practice-tab" data-tab="receive">${icon('headphones',15)} &nbsp; 수신 연습</button><button class="${practiceTab==='transmit'?'active':''}" data-action="practice-tab" data-tab="transmit">${icon('mic',15)} &nbsp; 송신 연습</button><button class="${practiceTab==='alphabet'?'active':''}" data-action="practice-tab" data-tab="alphabet">음성통화표</button><button class="${practiceTab==='guide'?'active':''}" data-action="practice-tab" data-tab="guide">실기 개념 · 준비</button></div>${practiceTab==='receive'?receivePage():practiceTab==='transmit'?transmitPage():practiceTab==='alphabet'?alphabetPage():practicalGuide()}`}
function receivePage(){const sample=DB.samples.find(s=>s.id===currentSample)||DB.samples[0];if(!sample)return '<div class="empty">수신 자료를 준비하고 있습니다.</div>';return `<div class="practice-layout"><section class="panel"><div class="section-head"><h2>듣고 받아쓰기</h2><span class="pill warm">첨부 원본 음원</span></div><p class="section-note">먼저 정답을 보지 않고 들으세요. 한 번 놓친 부분보다 다음 표현에 집중하는 것이 좋습니다.</p><div class="audio-select">${DB.samples.map(s=>`<button data-action="sample" data-id="${s.id}" class="${s.id===sample.id?'active':''}" aria-pressed="${s.id===sample.id}">샘플 ${s.id}</button>`).join('')}</div><audio id="sample-audio" controls preload="metadata" src="${esc(sample.audio)}">이 브라우저는 오디오 재생을 지원하지 않습니다.</audio><div class="actions">${button('5초 뒤로','audio-back','secondary small')}<label class="tiny" for="audio-speed">재생 속도</label><select id="audio-speed" class="input" style="padding:6px"><option value="0.75">0.75×</option><option value="1" selected>1.0×</option><option value="1.25">1.25×</option></select>${button('처음부터','audio-reset','ghost small')}</div><div class="spacer"></div><label for="dictation" class="tiny"><strong>나의 수신 답안</strong> · 영문과 숫자를 입력하세요</label><textarea id="dictation" class="dictation" spellcheck="false" autocomplete="off" autocapitalize="characters" placeholder="HEAR, WRITE, CHECK…">${esc(dictations[sample.id]||'')}</textarea><div class="actions" style="margin-top:14px">${button('답안 비교하기','grade-dictation','')}${button('답안 비우기','clear-dictation','secondary')}${button('정답 원문 보기','show-transcript','ghost')}</div><p class="field-hint">대소문자, 공백과 문장부호를 제외한 A–Z·0–9를 비교합니다. 삽입·누락을 고려한 문자 비교이며 공식 실기 채점 방식은 아닙니다.</p><div id="dictation-result" aria-live="polite"></div><div id="sample-transcript" hidden><h3>첨부 정답지 원문 · 샘플 ${sample.id}</h3><div class="answer-text">${esc(sample.answer||'')}</div>${sample.notes?notice(esc(Array.isArray(sample.notes)?sample.notes.join(' '):sample.notes),true):''}</div></section><aside><section class="panel"><div class="eyebrow">LISTENING ROUTINE</div><h2>반복할 때마다,<br>한 가지씩 개선하세요.</h2>${[['첫 번째','정답을 가리고 원래 속도로 전체를 듣습니다.'],['두 번째','비교 결과에서 놓친 문자와 숫자를 찾습니다.'],['세 번째','틀린 구간을 다시 듣고, 종이에 손으로 써봅니다.']].map(([a,b],i)=>`<div class="study-step"><span class="step-num">${i+1}</span><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}<a class="text-link" href="${esc(DB.materials.find(m=>m.title.includes('답안지 양식'))?.url||'#sources')}">수신 답안지 양식 열기 ${icon('external',13)}</a></section>${notice('첨부 음원과 정답지는 과거 학습 자료입니다. 실제 실기는 손으로 작성하므로 종이 답안지 연습도 함께 하세요.')}</aside></div>`}
function wireAudio(){const a=$('#sample-audio');if(a)a.addEventListener('error',()=>toast('음원을 불러오지 못했습니다. 자료실에서 원본 파일을 열어주세요.'))}
function normalize(s){return s.toUpperCase().replace(/[^A-Z0-9]/g,'')}
function alignText(expected,actual){const n=expected.length,m=actual.length;const dp=Array.from({length:n+1},()=>new Uint16Array(m+1));for(let i=0;i<=n;i++)dp[i][0]=i;for(let j=0;j<=m;j++)dp[0][j]=j;for(let i=1;i<=n;i++)for(let j=1;j<=m;j++)dp[i][j]=Math.min(dp[i-1][j]+1,dp[i][j-1]+1,dp[i-1][j-1]+(expected[i-1]===actual[j-1]?0:1));let i=n,j=m,items=[],correct=0,sub=0,del=0,ins=0;while(i||j){if(i&&j&&dp[i][j]===dp[i-1][j-1]+(expected[i-1]===actual[j-1]?0:1)){const ok=expected[i-1]===actual[j-1];items.push({e:expected[i-1],a:actual[j-1],type:ok?'good':'bad'});ok?correct++:sub++;i--;j--}else if(i&&dp[i][j]===dp[i-1][j]+1){items.push({e:expected[i-1],a:'_',type:'bad'});del++;i--}else{items.push({e:'–',a:actual[j-1],type:'extra'});ins++;j--}}return {items:items.reverse(),correct,sub,del,ins,rate:Math.round(Math.max(0,1-dp[n][m]/Math.max(n,m,1))*100)}}
function gradeDictation(){const s=DB.samples.find(s=>s.id===currentSample),a=$('#dictation').value;if(!a.trim()){toast('받아쓴 답안을 먼저 입력해 주세요.');return}const expected=normalize(s.answer),actual=normalize(a);if(actual.length>5000){toast('답안은 5,000자 이내로 입력해 주세요.');return}if(!expected){toast('비교할 정답이 확인되지 않은 자료입니다.');return}const r=alignText(expected,actual);$('#dictation-result').innerHTML=`<div class="spacer"></div><h3>문자 일치율 ${r.rate}%</h3><div class="metric-row"><div><b>${r.correct}</b><small>일치</small></div><div><b>${r.sub}</b><small>다른 문자</small></div><div><b>${r.del}</b><small>누락</small></div><div><b>${r.ins}</b><small>추가</small></div></div><p class="tiny muted">초록: 일치 · 빨강: 다름/누락 · 노랑: 추가<br>아래 밑줄(_)은 입력하지 않은 문자입니다. 문자에 마우스를 올리면 정답을 볼 수 있습니다.</p><div class="alignment">${r.items.map(x=>`<span class="${x.type}" title="정답: ${x.e}">${esc(x.a)}</span>`).join('')}</div>${notice('이 비율은 정규화한 두 문자열의 편집거리로 계산한 학습 지표입니다. 실제 시험 점수나 합격 여부로 환산하지 않습니다.')}`;$('#sample-transcript').hidden=false}
let transmitSeconds=180,transmitEnd=0;
function transmitPage(){const sample=DB.samples.find(s=>s.id==='B')||DB.samples[0];return `<div class="practice-layout"><section class="panel"><div class="section-head"><h2>소리 내어 송신하기</h2><span class="pill warm">50자/분 · 3분 연습</span></div><p class="section-note">음성통화표를 이용해 전문을 읽어보세요. 타이머와 녹음은 연습 보조 기능이며 발음이나 합격 여부를 자동 판정하지 않습니다.</p><div class="field"><label for="transmit-source">연습 전문</label><select id="transmit-source"><option value="random">무작위 문자 식별 드릴 · 150자</option>${DB.samples.map(s=>`<option value="${s.id}" ${s.id==='B'?'selected':''}>첨부 샘플 ${s.id} 전문 · ${normalize(s.answer).length}자</option>`).join('')}</select></div><div class="spacer"></div><div id="transmit-text" class="transmit-text">${esc(sample?.answer||randomGroups())}</div><div class="actions" style="margin-top:15px">${button('무작위 문자 드릴 생성','new-transmit','secondary small')}${button('통화표 보기','show-alphabet','ghost small')}</div><div class="practice-countdown" id="practice-clock">03:00</div><div class="actions">${button('타이머 시작','start-practice-timer','')}${button('일시정지','pause-practice-timer','secondary')}${button('초기화','reset-practice-timer','ghost')}</div><div class="spacer"></div><div class="panel" style="background:#f8faf5"><h3>내 송신 녹음하기</h3><p class="field-hint">녹음 시작 시 마이크 사용을 요청합니다. 녹음은 서버로 전송하지 않으며 이 화면에서 듣거나 파일로 저장할 수 있습니다.</p><div class="actions">${button(`${icon('mic',15)} 녹음 시작`,'record-start','secondary',`id="record-start"`)}${button('녹음 중지','record-stop','danger',`id="record-stop" disabled`)}</div><div id="record-result" aria-live="polite"></div></div></section><aside><div class="panel"><h2>송신 체크리스트</h2><ul class="checklist">${['시작 전 전문 전체와 헷갈리는 문자를 확인했다.','Alfa, Juliett 등 정해진 통화표를 사용했다.','숫자는 일반 영어 읽기와 통화표 표현을 구분했다.','너무 빠르게 읽지 않고 일정한 속도를 유지했다.','잘못 읽은 부분의 정정 절차를 공식 지침에서 확인했다.','녹음을 다시 듣고 불명확한 발음을 기록했다.'].map(t=>`<li><label><input type="checkbox"><span>${t}</span></label></li>`).join('')}</ul></div>${notice('무작위 전문은 문자 식별 연습을 위한 창작 자료입니다. 실제 출제 전문의 구성·숫자 비율·채점 조건을 재현한 것은 아닙니다.')}</aside></div>`}
function randomGroups(){const letters='ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';return Array.from({length:30},()=>Array.from({length:5},()=>letters[Math.floor(Math.random()*letters.length)]).join('')).join(' ')}
function alphabetPage(){return `<div class="grid-2"><section class="panel"><h2>ICAO 영문 음성통화표</h2><p class="section-note">각 항목을 누르면 브라우저 음성으로 들을 수 있습니다. 합성 음성은 표준 발음의 정확한 시범이 아니므로 원본 수신 음원과 함께 연습하세요.</p><div class="phonetic-grid">${alphabet.map(([l,w])=>`<button class="phonetic" data-action="speak" data-text="${w}" aria-label="${l}, ${w} 듣기"><b>${l}</b><span>${w}</span></button>`).join('')}</div><div id="tts-status" class="tts-state" aria-live="polite"></div>${notice('<b>Alfa</b>와 <b>Juliett</b>의 공식 철자를 기억하세요. 일반 단어 alpha, Juliet과 표기가 다릅니다. 현행 국내 별표에는 K·Z의 철자가 Kiro·Julu로 실려 있고 발음은 KEY LOH·ZOO LOO입니다. 위 표는 국제표 Kilo·Zulu를 표시합니다. 실기 개념 단원에서 원문 차이를 확인하세요.')}</section><section class="panel"><h2>숫자 발음 · 혼동 주의</h2><div class="table-wrap"><table><thead><tr><th>숫자</th><th>ICAO 발음 표기</th><th>일반 숫자 영어</th><th>국내 별표·실기 숫자 통화표</th></tr></thead><tbody>${[['0','ZE-RO','zero'],['1','WUN','one'],['2','TOO','two'],['3','TREE','three'],['4','FOW-er','four'],['5','FIFE','five'],['6','SIX','six'],['7','SEV-en','seven'],['8','AIT','eight'],['9','NIN-er','nine']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}<td>${esc((DB.phonetics||[]).find(p=>p.character===r[0])?.code||'')}</td></tr>`).join('')}</tbody></table></div>${notice('첨부 실기 약어표에 있는 국제 숫자 통화표(예: UNAONE, BISSOTWO)는 ICAO 항공 통신의 숫자 발음표와 구분하세요. 실기에서는 최신 KCA 안내와 감독 지시에 따라 사용합니다.',true)}<a href="#practical" class="text-link" data-action="practice-guide">실기 자료와 통화표 차이 읽기 ${icon('arrow',13)}</a></section></div>`}
function practicalGuide(){const ch=DB.chapters.filter(c=>c.category==='practical');return `${notice('KCA 공식 안내의 실기는 무선통신술 송신·수신입니다. 영어 50자/분, 각각 3분을 기준으로 안내하며, 각 과목 40점 이상·평균 60점 이상이 합격 기준입니다. 최신 시행 안내와 수험표도 확인하세요.')}<div class="chapter-list">${ch.map((c,i)=>`<a class="chapter-row" href="#chapter/${c.id}"><span class="chapter-index">${i+1}</span><div><h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p></div><span class="end">${icon('chevron',16)}</span></a>`).join('')}</div><div class="spacer"></div><a class="btn secondary" href="https://www.cq.or.kr/qh_quagm02_003.do" target="_blank" rel="noopener">KCA 공식 시험 안내 ${icon('external',14)}</a>`}
function vocabularyPage(){const groups=[...new Set(DB.vocabulary.map(v=>v.group))];return `${pageHead('AVIATION VOCABULARY','단어를 넘어, 문맥으로.','뜻과 예문을 함께 익히는 항공영어 단어장.','<a class="btn secondary" href="#english">개념 목차로</a>')}<div class="filter-bar"><input id="vocab-search" class="input" placeholder="용어·뜻·예문 검색" aria-label="단어장 검색"><select id="vocab-group" class="input" aria-label="단어 분야"><option value="">모든 분야</option>${groups.map(g=>`<option>${esc(g)}</option>`).join('')}</select></div><div id="vocab-items" class="vocab-grid">${vocabCards(DB.vocabulary)}</div>`}
function vocabCards(arr){return arr.map(v=>`<article class="vocab-card"><span class="pill purple">${esc(v.group)}</span><h3>${esc(v.term)}</h3><p>${esc(v.meaning)}</p><p class="example">${esc(v.example)}</p></article>`).join('')||'<div class="empty">검색 결과가 없습니다.</div>'}
function sourcesPage(){return `${pageHead('SOURCES & COVERAGE','근거를 확인하며 공부하세요.','2026년 10월 25일 확인 자료 · 법령 시행일과 자료의 적용 범위를 함께 표시합니다.')}<div class="tabs"><a href="#legal">현행 조문 읽기 ↗</a><button class="active" data-action="source-tab" data-tab="official">공식 자료 · 법령</button><button data-action="source-tab" data-tab="coverage">학습 범위 점검표</button><button data-action="source-tab" data-tab="originals">첨부 원본 자료</button></div><div class="source-pane" id="source-official">${notice('이 사이트는 기준일에 확인한 자료로 작성된 고정판입니다. 법령 개정이 자동 반영되지는 않습니다. 시험 전 원문의 현행 시행일과 KCA 공지를 다시 확인하세요.')}<div class="grid-2">${DB.sources.map(s=>`<article class="source-card"><h3>${esc(s.title)}</h3><div class="meta"><span class="pill ${s.verified===false?'warm':''}">${s.verified===false?'확인 범위 제한':'출처 확인'}</span>${s.effective?`<span class="tiny muted">${esc(s.effective)}</span>`:''}</div><p>${esc(s.note||'단원별 관련 근거로 연결한 참고 자료입니다.')}</p><a href="${esc(s.url)}" target="_blank" rel="noopener" class="text-link">원문 열기 ${icon('external',12)}</a></article>`).join('')}</div></div><div class="source-pane" id="source-coverage" hidden>${notice('아래 표는 이 학습실의 주제별 수록 현황입니다. 공개 자료로 확인 가능한 범위를 정리했으며, 비공개 CBT 문제은행의 모든 개념·문항을 빠짐없이 재현했다는 보증은 아닙니다. 수치·별표는 연결된 현행 원문을 함께 확인하세요.')}<div class="panel"><h2>출제 범위와 보충 학습의 연결</h2><div class="table-wrap"><table><thead><tr><th style="width:18%">영역</th><th>세부 학습 내용</th><th style="width:24%">수록·확인 상태</th></tr></thead><tbody>${DB.coverage.map(c=>`<tr><td><strong>${esc(c.area)}</strong></td><td>${esc((c.items||[]).join(' · '))}</td><td><span class="pill ${/제한|미확인|대조/.test(c.status||'')?'warm':''}">${esc(c.status||'수록')}</span><div class="tiny muted" style="margin-top:8px">${esc(c.note||'')}</div></td></tr>`).join('')}</tbody></table></div></div></div><div class="source-pane" id="source-originals" hidden>${notice('첨부한 기출·답안·실기 자료 16개를 원본 그대로 보관했습니다. 과거 법령 문항과 정답은 당시 기준이며, 최신 법령의 정답으로 사용하지 않습니다. 스캔·도표 자료는 원본을 직접 확인하세요.',true)}<div class="material-grid">${DB.materials.map(m=>`<a class="material-item" href="${esc(m.url)}" target="_blank" rel="noopener"><div class="icon-box ${m.type?.toLowerCase()==='mp3'?'warm':''}">${icon(m.type?.toLowerCase()==='mp3'?'headphones':'folder',19)}</div><div><h3>${esc(m.title)}</h3><p>${esc((m.type||'FILE').toUpperCase())} · ${esc(m.note||'첨부 원본 자료')}</p></div>${icon('external',13)}</a>`).join('')}</div></div>`}
function openModal(html){lastFocus=document.activeElement;$('#overlay').hidden=false;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="학습실 대화상자">${html}</section></div>`;$('#overlay').querySelector('input,button,a')?.focus()}
function closeModal(){if($('#overlay').hidden)return;$('#overlay').hidden=true;$('#overlay').innerHTML='';lastFocus?.focus?.()}
function searchModal(){openModal(`<div class="modal-header">${icon('search',20)}<input id="global-search" placeholder="예: 조난, 허가, MAYDAY, METAR" aria-label="전체 개념 검색"><button data-action="close-modal" class="modal-close" aria-label="닫기">×</button></div><div class="modal-body" id="search-results"><p class="muted tiny">개념 제목과 본문, 단어 뜻을 검색합니다.</p><div class="actions">${['전파법','조난','호출부호','METAR','readback'].map(s=>button(s,'search-term','secondary small',`data-term="${s}"`)).join('')}</div></div>`);$('#global-search').focus()}
function runSearch(term){const v=term.toLowerCase().trim();if(!v){$('#search-results').innerHTML='<p class="muted tiny">검색어를 입력해 주세요.</p>';return}const found=DB.chapters.filter(c=>[c.title,c.summary,...c.topics.flatMap(t=>[t.title,t.body,...(t.bullets||[])])].join(' ').toLowerCase().includes(v)).slice(0,25);const vocab=DB.vocabulary.filter(x=>[x.term,x.meaning,x.example].join(' ').toLowerCase().includes(v)).slice(0,6);$('#search-results').innerHTML=`<p class="muted tiny">관련 단원 ${found.length}개${found.length===25?' 이상':''} · 단어 ${vocab.length}개</p>${found.map(c=>`<a class="search-result" href="#chapter/${c.id}">${chip(c.category)}<h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p></a>`).join('')}${vocab.map(x=>`<a class="search-result" href="#vocabulary"><span class="pill purple">단어장</span><h3>${esc(x.term)} · ${esc(x.meaning)}</h3><p>${esc(x.example)}</p></a>`).join('')}${!found.length&&!vocab.length?'<div class="empty">다른 용어나 짧은 검색어를 입력해 보세요.</div>':''}`}
function confirmModal(title,text,action,label='확인'){openModal(`<div class="modal-header"><h3 style="margin:0;flex:1">${title}</h3><button data-action="close-modal" class="modal-close" aria-label="닫기">×</button></div><div class="modal-body"><p>${text}</p><div class="actions">${button(label,action,'')}${button('취소','close-modal','secondary')}</div></div>`)}
function downloadJSON(obj,name){const u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function speak(text){if(!('speechSynthesis'in window)){toast('이 브라우저는 음성 재생을 지원하지 않습니다.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.8;const voice=speechSynthesis.getVoices().find(x=>x.lang.startsWith('en'));if(voice)u.voice=voice;u.onstart=()=>{if($('#tts-status'))$('#tts-status').textContent=`${text} 재생 중`};u.onend=()=>{if($('#tts-status'))$('#tts-status').textContent=`${text} 재생 완료`};u.onerror=()=>toast('음성 재생을 사용할 수 없습니다. 원본 음원을 이용해 주세요.');speechSynthesis.speak(u)}
async function startRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('이 브라우저에서 녹음을 지원하지 않습니다. 기기의 녹음 앱을 이용해 주세요.');return}try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});recordChunks=[];recording=new MediaRecorder(recordStream);recording.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data)};recording.onstop=()=>{recordStream.getTracks().forEach(t=>t.stop());if(recordURL)URL.revokeObjectURL(recordURL);recordURL=URL.createObjectURL(new Blob(recordChunks,{type:recording.mimeType}));const el=$('#record-result');if(el)el.innerHTML=`<p class="tiny muted">녹음이 완료되었습니다. 화면을 떠나기 전에 필요한 파일을 저장하세요.</p><audio controls src="${recordURL}"></audio><a class="btn secondary small" download="aeronote-transmission.${recording.mimeType.includes('mp4')?'m4a':'webm'}" href="${recordURL}">녹음 파일 저장</a>`;if($('#record-start'))$('#record-start').disabled=false;if($('#record-stop'))$('#record-stop').disabled=true;};recording.start();$('#record-start').disabled=true;$('#record-stop').disabled=false;$('#record-result').innerHTML='<p class="tiny wrong-text" role="status">● 녹음 중입니다. 끝나면 녹음 중지를 눌러주세요.</p>';}catch(e){toast('마이크를 사용할 수 없습니다. 브라우저의 마이크 권한을 확인해 주세요.')}}
function updatePracticeClock(){const el=$('#practice-clock');if(el)el.textContent=`${String(Math.floor(transmitSeconds/60)).padStart(2,'0')}:${String(transmitSeconds%60).padStart(2,'0')}`}
function startPracticeTimer(){clearInterval(practiceTimer);if(transmitSeconds<=0)transmitSeconds=180;transmitEnd=Date.now()+transmitSeconds*1000;practiceTimer=setInterval(()=>{transmitSeconds=Math.max(0,Math.ceil((transmitEnd-Date.now())/1000));updatePracticeClock();if(!transmitSeconds){clearInterval(practiceTimer);toast('3분 연습이 끝났습니다.');if(recording?.state==='recording')recording.stop()}},250)}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;switch(a){case'skip-main':e.preventDefault();$('#main').focus();break;case'menu':$('#sidebar').classList.toggle('open');break;case'search':searchModal();break;case'close-modal':closeModal();break;case'search-term':$('#global-search').value=el.dataset.term;runSearch(el.dataset.term);break;case'bookmark':state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();navigate();toast(state.bookmarks.includes(id)?'북마크에 저장했습니다.':'북마크에서 해제했습니다.');break;case'complete':state.completed=state.completed.includes(id)?state.completed.filter(x=>x!==id):[...state.completed,id];save();navigate();toast(state.completed.includes(id)?'학습 완료를 기록했습니다.':'학습 완료 표시를 해제했습니다.');break;case'print':window.print();break;case'scroll-topic':e.preventDefault();document.getElementById(el.dataset.topic)?.scrollIntoView({behavior:'smooth'});break;case'start-quiz':startQuiz();break;case'answer':{const q=state.quiz;const qid=q.ids[q.index];if(!q.revealed.includes(qid)){q.answers[qid]=Number(el.dataset.index);save();$('#main').innerHTML=activeQuiz();startQuizTimerSafe()}break}case'flag':{const q=state.quiz,qid=q.ids[q.index];q.flags=q.flags.includes(qid)?q.flags.filter(x=>x!==qid):[...q.flags,qid];save();$('#main').innerHTML=activeQuiz();startQuizTimerSafe();break}case'reveal':{const q=state.quiz,qid=q.ids[q.index];if(q.answers[qid]===undefined){toast('답을 먼저 선택하세요.');break}q.revealed.push(qid);save();$('#main').innerHTML=activeQuiz();startQuizTimerSafe();break}case'prev-question':state.quiz.index=Math.max(0,state.quiz.index-1);save();navigate();break;case'next-question':state.quiz.index=Math.min(state.quiz.ids.length-1,state.quiz.index+1);save();navigate();break;case'jump-question':state.quiz.index=Number(el.dataset.index);save();navigate();break;case'submit-quiz':{const q=state.quiz,left=q.ids.length-Object.keys(q.answers).length;confirmModal('답안을 제출할까요?',left?`아직 ${left}문항에 답하지 않았습니다. 미응답은 오답으로 기록됩니다.`:'답안을 채점하고 해설을 확인합니다.','confirm-submit','제출하고 채점');break}case'confirm-submit':finishQuiz();break;case'new-quiz':state.quiz=null;save();navigate();break;case'cancel-quiz':confirmModal('이번 연습을 종료할까요?','진행 중인 답안은 삭제되며 연습 기록에 추가되지 않습니다. 다른 화면으로 이동하면 답안을 유지한 채 나중에 이어서 풀 수 있습니다.','new-quiz','연습 종료');break;case'retry-wrong':if(state.quiz&&!state.quiz.finished){confirmModal('진행 중인 연습이 있습니다.','오답 연습을 시작하면 진행 중인 답안을 교체합니다.','confirm-retry','오답 연습 시작')}else startQuiz(true);break;case'confirm-retry':closeModal();startQuiz(true);break;case'remove-wrong':state.wrong=state.wrong.filter(x=>x!==id);save();navigate();break;case'review-tab':$$('.review-pane').forEach(p=>p.hidden=p.id!==`review-${el.dataset.tab}`);$$('.tabs button').forEach(b=>b.classList.toggle('active',b===el));break;case'source-tab':$$('.source-pane').forEach(p=>p.hidden=p.id!==`source-${el.dataset.tab}`);$$('.tabs button').forEach(b=>b.classList.toggle('active',b===el));break;case'practice-tab':practiceTab=el.dataset.tab;transmitSeconds=180;navigate();break;case'practice-guide':e.preventDefault();practiceTab='guide';navigate();break;case'sample':if($('#dictation'))dictations[currentSample]=$('#dictation').value;currentSample=id;navigate();break;case'audio-back':$('#sample-audio').currentTime=Math.max(0,$('#sample-audio').currentTime-5);break;case'audio-reset':$('#sample-audio').pause();$('#sample-audio').currentTime=0;break;case'grade-dictation':gradeDictation();break;case'clear-dictation':$('#dictation').value='';dictations[currentSample]='';$('#dictation-result').innerHTML='';break;case'show-transcript':$('#sample-transcript').hidden=!$('#sample-transcript').hidden;break;case'new-transmit':$('#transmit-source').value='random';$('#transmit-text').textContent=randomGroups();break;case'show-alphabet':practiceTab='alphabet';navigate();break;case'speak':speak(el.dataset.text);break;case'start-practice-timer':startPracticeTimer();break;case'pause-practice-timer':clearInterval(practiceTimer);break;case'reset-practice-timer':clearInterval(practiceTimer);transmitSeconds=180;updatePracticeClock();break;case'record-start':await startRecording();break;case'record-stop':if(recording?.state==='recording')recording.stop();break;case'export-state':downloadJSON({version:1,exported:new Date().toISOString(),state},'aeronote-study-backup.json');toast('학습 기록 백업 파일을 저장했습니다.');break;case'reset-state':confirmModal('학습 기록을 초기화할까요?','현재 브라우저의 진행률, 오답, 메모, 북마크를 삭제합니다. 필요한 경우 먼저 백업해 주세요.','confirm-reset','초기화');break;case'confirm-reset':state={completed:[],bookmarks:[],notes:{},wrong:[],history:[],lastChapter:null,quiz:null,visits:[]};save();navigate();toast('학습 기록을 초기화했습니다.');break}});
function startQuizTimerSafe(){clearInterval(timerHandle);startQuizTimer()}
document.addEventListener('input',e=>{if(e.target.id==='lesson-note'){state.notes[e.target.dataset.chapter]=e.target.value;save();$('#note-status').textContent='메모가 저장되었습니다.'}if(e.target.id==='global-search')runSearch(e.target.value);if(e.target.id==='dictation')dictations[currentSample]=e.target.value;if(e.target.id==='vocab-search')filterVocab();if(e.target.id==='legal-search')filterLegal()});
function filterVocab(){const q=$('#vocab-search').value.toLowerCase(),g=$('#vocab-group').value;$('#vocab-items').innerHTML=vocabCards(DB.vocabulary.filter(v=>(!g||g===v.group)&&[v.term,v.meaning,v.example].join(' ').toLowerCase().includes(q)))}
document.addEventListener('change',async e=>{if(e.target.id==='audio-speed')$('#sample-audio').playbackRate=Number(e.target.value);if(e.target.id==='transmit-source'){const v=e.target.value;$('#transmit-text').textContent=v==='random'?randomGroups():DB.samples.find(s=>s.id===v)?.answer||''}if(e.target.id==='vocab-group')filterVocab();if(e.target.id==='legal-book')filterLegal();if(e.target.id==='import-state'){const f=e.target.files[0];if(!f)return;if(f.size>3000000){toast('백업 파일이 너무 큽니다.');return}try{const d=JSON.parse(await f.text()),s=d.state;if(d.version!==1||!s||!Array.isArray(s.completed)||!Array.isArray(s.wrong)||!s.notes||typeof s.notes!=='object')throw Error();const validCh=new Set(DB.chapters.map(c=>c.id)),validQ=new Set(DB.questions.map(q=>q.id));const restored={completed:s.completed.filter(x=>validCh.has(x)),bookmarks:(Array.isArray(s.bookmarks)?s.bookmarks:[]).filter(x=>validCh.has(x)),wrong:s.wrong.filter(x=>validQ.has(x)),notes:Object.fromEntries(Object.entries(s.notes).filter(([k,v])=>validCh.has(k)&&typeof v==='string').map(([k,v])=>[k,v.slice(0,100000)])),history:(Array.isArray(s.history)?s.history:[]).filter(h=>typeof h.label==='string'&&Number.isFinite(h.date)&&Number.isFinite(h.total)&&h.total>0&&Number.isFinite(h.correct)&&h.correct>=0&&h.correct<=h.total).slice(0,100),lastChapter:validCh.has(s.lastChapter)?s.lastChapter:null,quiz:null,visits:[]};window.pendingImport=restored;confirmModal('백업 기록을 불러올까요?','현재 브라우저의 기록을 백업 내용으로 교체합니다. 진행 중인 연습은 복원하지 않습니다.','confirm-import','불러오기')}catch{toast('올바른 AERO NOTE 백업 파일이 아닙니다.')}}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="confirm-import"]')){state=window.pendingImport;save();navigate();toast('백업 기록을 불러왔습니다.')}if(e.target.classList.contains('modal-backdrop'))closeModal();if(!e.target.closest('#sidebar')&&!e.target.closest('[data-action="menu"]'))$('#sidebar').classList.remove('open')});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchModal()}if(e.key==='Escape'){closeModal();$('#sidebar').classList.remove('open')}if(e.key==='Tab'&&!$('#overlay').hidden){const focusables=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',navigate);window.addEventListener('beforeunload',()=>{if(recording?.state==='recording')recording.stop();recordStream?.getTracks().forEach(t=>t.stop())});
navigate();

function legalPage(){const books=DB.legalBooks||[];return `${pageHead('STATUTE READER','현행 조문 읽기','개념에서 원문으로. 주요 법령의 모든 본문 조문을 검색하고 표를 확인하세요.','<a href="#law" class="btn secondary">개념 목차로</a>')}${notice('국가법령정보센터에서 2026.10.25 확인한 본문 조문을 수록했습니다. 삭제 조문도 표시합니다. 별표·별지는 아래 목록에서 확인할 수 있습니다. 주요 항공 관련 별표 PDF는 사이트에 보관하고 나머지는 공식 파일로 연결했습니다. 부칙과 개정 이력은 공식 원문을 확인하세요. 법령 본문 전체에는 시험 범위를 넘어서는 조항도 포함됩니다.')}<div class="filter-bar"><select id="legal-book" class="input" aria-label="법령 선택">${books.map(b=>`<option value="${b.id}" ${b.id==='ops'?'selected':''}>${esc(b.title)}</option>`).join('')}</select><input id="legal-search" class="input" placeholder="조문 번호 또는 내용 검색 · 예: 제63조, 조난, 주파수" aria-label="조문 검색"></div><div id="legal-results">${legalArticles('ops','')}</div>`}
function legalArticles(id,query){const b=(DB.legalBooks||[]).find(x=>x.id===id);if(!b)return '<div class="empty">법령 본문을 준비하고 있습니다.</div>';const q=query.toLowerCase().replace(/\s/g,'');const arr=b.articles.filter(a=>[a.title,...a.blocks.map(t=>t.text||'')].join('').toLowerCase().replace(/\s/g,'').includes(q));return `<div class="section-head"><div class="tiny muted">시행 ${b.effective} · ${arr.length} / ${b.articles.length}개 본문 조문</div><a href="${esc(b.url)}" target="_blank" rel="noopener" class="text-link">별표·부칙 포함 공식 원문 ${icon('external',12)}</a></div>${legalAnnexes(b,query)}<div class="panel law-reader">${arr.map(a=>`<details class="law-article"><summary><strong>${esc(a.title)}</strong>${/삭제/.test(a.blocks[0]?.text||'')?'<span class="pill outline">삭제 조문</span>':''}</summary><div class="law-body">${a.blocks.map(bl=>bl.text?`<p>${esc(bl.text)}</p>`:bl.image?`<figure><a href="${esc(bl.image)}" target="_blank" rel="noopener"><img loading="lazy" src="${esc(bl.image)}" alt="${esc(bl.alt)}"></a><figcaption>${esc(bl.alt)} · 표를 누르면 확대해서 볼 수 있습니다. <a href="${esc(bl.remote)}" target="_blank" rel="noopener">공식 원본</a></figcaption></figure>`:'').join('')}</div></details>`).join('')||'<p class="muted">일치하는 조문이 없습니다.</p>'}</div>`}
function filterLegal(){$('#legal-results').innerHTML=legalArticles($('#legal-book').value,$('#legal-search').value)}

function legalAnnexes(b,query){const q=query.toLowerCase().replace(/\s/g,'');const items=(b.annexes||[]).filter(a=>a.title.toLowerCase().replace(/\s/g,'').includes(q));if(!items.length)return '';return `<details class="panel" style="margin-bottom:18px" ${q?'open':''}><summary style="cursor:pointer;font-weight:600;font-size:13px">별표 · 별지 자료 ${items.length}개</summary><div class="spacer"></div><div class="material-grid">${items.map(a=>`<a class="material-item" href="${esc(a.local||a.url)}" target="_blank" rel="noopener"><div><h3>${esc(a.title)}</h3><p>${a.local?'공식 PDF 보관본':'국가법령정보센터 공식 PDF'} · ${b.effective} 시행본</p></div>${icon('external',12)}</a>`).join('')}</div></details>`}
